{
    AVANumberSeqModuleBP        locNnumberSeqModule;
    //NumberSeq                   locNumberSeq;
    //KCS_KBVBuildingProjectID    locKCS_KBVBuildingProjectID;

    ttsbegin;
    locNnumberSeqModule = new AVANumberSeqModuleBP();
    locNnumberSeqModule.load();
    ttscommit;
}
